        object("Keep favorite recordings").click();AudioClearJob.State both=audioSelection(fixture,2);assertFalse(both.plan.keepFavorites);nativeWindow("privacy-recordings-favorites-included");View cancelled=retainConfirmation("Confirm recording deletion");object("Keep recordings").click();assertTrue(device.wait(Until.gone(By.desc("Confirm recording deletion")),5000));i.runOnMainSync(cancelled::performClick);audioDone(fixture);try(Store store=new Store(c,name)){assertEquals(2,store.rows("SELECT id FROM clips").size());}assertTrue(wav.isFile());assertTrue(child.isFile());
