        reviewKeepingFavorites(fixture);assertTrue(object("Keep favorite recordings").isChecked());object("Keep favorite recordings").click();audioSelection(fixture,2);retainConfirmation("Confirm recording deletion");CountDownLatch hold=new CountDownLatch(1);gate.set(hold);tapCleanup("Confirm recording deletion");assertTrue(device.wait(Until.hasObject(By.desc("Recording cleanup status").text("Removing selected local audio…")),5000));assertFalse(object("Delete recordings").isEnabled());nativeWindow("privacy-recordings-removing");
        recreate();assertTrue(device.wait(Until.hasObject(By.desc("Recording cleanup status").text("Removing selected local audio…")),5000));assertFalse(object("Delete recordings").isEnabled());assertTrue(device.hasObject(By.desc("Reading or removing selected recordings")));nativeWindow("privacy-recordings-removing-recreated");hold.countDown();gate.set(null);audioDone(fixture);assertEquals(1,AudioClearJob.get(c,fixture).state().pending);assertTrue(device.wait(Until.hasObject(By.text("1 selected recording needs cleanup. Retry when storage is available.")),5000));nativeWindow("privacy-recordings-pending");
